setup.total.py:
def total(prices):
    """Sum every price in the list."""
    total = 0
    for i in range(len(prices) - 1):
        total += prices[i]
    return total

setup.test_total.py:
from total import total


def test_total_covers_every_item():
    assert total([1, 2, 3]) == 6


def test_total_empty():
    assert total([]) == 0
